import { Component, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { SaobracajnaDozvola, SaobracajnaService } from '../../services/saobracajna.service';
import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

declare var bootstrap: any;
interface NoviZahtev {
  marka: string;
  model: string;
  kubikaza: number;
  godiste: number;
  vrstaPogona: string;
  tablice: string;
}
@Component({
  selector: 'app-saobracajna',
  templateUrl: './saobracajna.component.html',
  styleUrls: ['./saobracajna.component.css']
})
export class SaobracajnaComponent implements OnInit, AfterViewInit {

  @ViewChild('saobracajnaModal', { static: false }) saobracajnaModalRef!: ElementRef;

  saobracajne: SaobracajnaDozvola[] = [];
  token: string = '';
  rola: string = '';
  trenutnaGodina: number = new Date().getFullYear();

  noviZahtev: NoviZahtev = {
    marka: '',
    model: '',
    kubikaza: 0,
    godiste: 0,
    vrstaPogona: '',
    tablice: ''
  };
  modalInstance: any;

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'success';

  constructor(private saobracajnaService: SaobracajnaService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajSaobracajne();
  }

  ngAfterViewInit(): void {
    if (this.saobracajnaModalRef && this.saobracajnaModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.saobracajnaModalRef.nativeElement);
    }
  }

  openSaobracajnaModal(): void {
    if (this.modalInstance) this.modalInstance.show();
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    this.saobracajnaService.podnesiZahtev(this.noviZahtev).subscribe({
      next: res => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm();
        this.ucitajSaobracajne();

        this.alertType = 'success';
        this.alertMessage = res || 'Zahtev uspešno podnet!';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertType = 'error';
        this.alertMessage = err?.error || 'Greška pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });

  }

  ucitajSaobracajne(): void {
    this.saobracajnaService.dohvatiSve().subscribe({
      next: (res) => this.saobracajne = res,
      error: (err) => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    return this.saobracajne.some(z => z.status === 'CEKANJE' || z.status === 'DOZVOLJEN');
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

  prihvatiZahtev(id: number) {
    this.saobracajnaService.odobriZahtev(id).subscribe({
      next: res => {
        this.ucitajSaobracajne();
        this.alertMessage = res?.message || 'Zahtev odobren!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        this.alertMessage = err.error?.message || 'Greška pri odobravanju.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.saobracajnaService.odbijZahtev(id).subscribe({
      next: res => {
        this.ucitajSaobracajne();
        this.alertMessage = res?.message || 'Zahtev odbijen!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        this.alertMessage = err.error?.message || 'Greška pri odbijanju.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  produziSaobracajnu() {
    this.saobracajnaService.produzi().subscribe({
      next: (res: any) => {
        this.ucitajSaobracajne();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Saobraćajna je produžena!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Dozvola još nije spremna za produženje (više od mesec dana do isteka).';
        this.showAlert = true;
      }
    });
  }

  get mozeProduziti(): boolean {
    return this.saobracajne.some(z => z.status === 'DOZVOLJEN');
  }
}
<div class="container mt-5">

  <app-custom-alert
    *ngIf="showAlert"
    [message]="alertMessage"
    [type]="alertType"
    (closed)="closeAlert()">
  </app-custom-alert>

  <div class="d-flex justify-content-center mb-4 gap-2" *ngIf="!isEmployer">
    <button class="btn btn-primary" (click)="openSaobracajnaModal()">
      Zahtev za saobraćajnu dozvolu
    </button>

    <button class="btn btn-warning" (click)="produziSaobracajnu()" *ngIf="mozeProduziti">
      Produži saobraćajnu dozvolu
    </button>
  </div>


  <h3 class="mb-3 text-center">
    {{ isEmployer ? 'Zahtevi za saobraćajne dozvole' : 'Moje saobraćajne dozvole' }}
  </h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Adresa</th>
        <th>Marka</th>
        <th>Model</th>
        <th>Kubikaža</th>
        <th>Godište</th>
        <th>Vrsta pogona</th>
        <th>Tablice</th>
        <th>Izdato</th>
        <th>Važi do</th>
        <th>Broj dozvole</th>
        <th *ngIf="isEmployer">Status</th>
        <th *ngIf="isEmployer">Akcija</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let s of saobracajne; let i = index">
        <tr *ngIf="isEmployer || s.status === 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ s.ime }}</td>
          <td>{{ s.prezime }}</td>
          <td>{{ s.adresa }}</td>
          <td>{{ s.marka }}</td>
          <td>{{ s.model }}</td>
          <td>{{ s.kubikaza }}</td>
          <td>{{ s.godiste }}</td>
          <td>{{ s.vrstaPogona }}</td>
          <td>{{ s.tablice }}</td>
          <td>{{ s.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
          <td>{{ s.datumVazenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ s.brojDozvole }}</td>
          <td *ngIf="isEmployer">{{ s.status }}</td>
          <td *ngIf="isEmployer">
            <ng-container *ngIf="s.status !== 'DOZVOLJEN' && s.status !== 'ODBIJEN' && s.status !== 'IZGUBLJEN'">
              <button class="btn btn-success btn-sm me-2" (click)="prihvatiZahtev(s.id)">Prihvati</button>
              <button class="btn btn-danger btn-sm" (click)="odbijZahtev(s.id)">Odbij</button>
            </ng-container>
          </td>
        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>

  <div class="modal fade" id="saobracajnaModal" #saobracajnaModal tabindex="-1" aria-labelledby="saobracajnaModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="saobracajnaModalLabel">Podnesi zahtev za saobraćajnu dozvolu</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Zatvori"></button>
        </div>
        <div class="modal-body">
          <form #saobracajnaForm="ngForm" (ngSubmit)="podnesiZahtev(saobracajnaForm)">

            <div class="mb-3">
              <label for="marka" class="form-label">Marka</label>
              <input type="text" class="form-control" id="marka" name="marka"
                     [(ngModel)]="noviZahtev.marka" required #markaCtrl="ngModel">
              <div class="text-danger" *ngIf="markaCtrl.invalid && markaCtrl.touched">
                Marka je obavezna.
              </div>
            </div>

            <div class="mb-3">
              <label for="model" class="form-label">Model</label>
              <input type="text" class="form-control" id="model" name="model"
                     [(ngModel)]="noviZahtev.model" required #modelCtrl="ngModel">
              <div class="text-danger" *ngIf="modelCtrl.invalid && modelCtrl.touched">
                Model je obavezan.
              </div>
            </div>

            <div class="mb-3">
              <label for="kubikaza" class="form-label">Kubikaža</label>
              <input type="number" class="form-control" id="kubikaza" name="kubikaza"
                     [(ngModel)]="noviZahtev.kubikaza" required #kubikazaCtrl="ngModel">
              <div class="text-danger" *ngIf="kubikazaCtrl.invalid && kubikazaCtrl.touched">
                Kubikaža je obavezna.
              </div>
            </div>

            <div class="mb-3">
              <label for="godiste" class="form-label">Godište</label>
              <input type="number" class="form-control" id="godiste" name="godiste"
                     [(ngModel)]="noviZahtev.godiste"
                     [max]="trenutnaGodina"
                     required #godisteCtrl="ngModel">
              <div class="text-danger" *ngIf="godisteCtrl.errors?.['required'] && godisteCtrl.touched">
                Godište je obavezno.
              </div>
              <div class="text-danger" *ngIf="godisteCtrl.errors?.['max'] && godisteCtrl.touched">
                Godište ne može biti posle {{ trenutnaGodina }}.
              </div>
            </div>

            <div class="mb-3">
              <label for="vrstaPogona" class="form-label">Vrsta pogona</label>
              <input type="text" class="form-control" id="vrstaPogona" name="vrstaPogona"
                     [(ngModel)]="noviZahtev.vrstaPogona" required #vrstaCtrl="ngModel">
              <div class="text-danger" *ngIf="vrstaCtrl.invalid && vrstaCtrl.touched">
                Vrsta pogona je obavezna.
              </div>
            </div>

            <div class="mb-3">
              <label for="tablice" class="form-label">Tablice</label>
              <input type="text" class="form-control" id="tablice" name="tablice"
                     [(ngModel)]="noviZahtev.tablice"
                     pattern="^[A-Z]{2}-\d{3,4}-[A-Z]{2}$"
                     required #tabliceCtrl="ngModel">
              <div class="text-danger" *ngIf="tabliceCtrl.errors?.['required'] && tabliceCtrl.touched">
                Tablice su obavezne.
              </div>
              <div class="text-danger" *ngIf="tabliceCtrl.errors?.['pattern'] && tabliceCtrl.touched">
                Format tablica mora biti npr. VA-1022-TX.
              </div>
            </div>


            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary" [disabled]="saobracajnaForm.invalid">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
